import React, { useEffect, useState } from "react";
import api from "../api";

const AbsenMahasiswa = () => {
  const [presensi, setPresensi] = useState([]); // Inisialisasi sebagai array kosong
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await api.get("/mahasiswa/presensi/me");
        const data = response.data.presensi || []; // Pastikan nilai default adalah array
        setPresensi(data);
      } catch (error) {
        console.error("Error fetching presensi:", error);
        setPresensi([]); // Default ke array kosong jika terjadi error
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleSubmitPresensi = async (presensiId) => {
    try {
      const response = await api.post("/mahasiswa/presensi/submit", {
        presensi_id: presensiId,
      });
      setMessage(response.data.message);

      // Update presensi yang telah disubmit
      setPresensi((prevPresensi) =>
        prevPresensi.map((item) =>
          item.id === presensiId ? { ...item, is_open: false } : item
        )
      );
    } catch (error) {
      console.error("Error submitting presensi:", error);
      setMessage("Gagal melakukan presensi.");
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h2>Daftar Presensi</h2>
      {message && <p>{message}</p>}
      <table>
        <thead>
          <tr>
            <th>Hari</th>
            <th>Waktu Mulai</th>
            <th>Waktu Selesai</th>
            <th>Aksi</th>
          </tr>
        </thead>
        <tbody>
          {presensi.length > 0 ? (
            presensi.map((item, index) => (
              <tr key={index}>
                <td>{item.hari}</td>
                <td>{item.start_time}</td>
                <td>{item.end_time}</td>
                <td>
                  {item.is_open ? (
                    <button onClick={() => handleSubmitPresensi(item.id)}>
                      Submit Presensi
                    </button>
                  ) : (
                    "Presensi Ditutup"
                  )}
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="4">Tidak ada data presensi tersedia.</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default AbsenMahasiswa;
